python3 -c "
import json,glob
for f in sorted(glob.glob('output/dry-run-*.json')):
    try:
        data = json.load(open(f))
    except Exception as e:
        print(f, 'ERR', e); continue
    if isinstance(data, dict):
        data = data.get('jobs') or data.get('data') or [data]
    if not isinstance(data, list):
        continue
    for item in data:
        loc = json.dumps(item.get('location','')) if isinstance(item, dict) else ''
        print(f, '|', item.get('title') if isinstance(item, dict) else item, '|', loc)
